import React, { useRef, useEffect, useState, useCallback } from 'react';
import { BreakoutGame, GAME_WIDTH, GAME_HEIGHT, Paddle, Ball, Brick } from './game';

const BreakoutPage: React.FC = () => {
  const canvasRef = useRef<HTMLCanvasElement>(null);
  const gameRef = useRef<BreakoutGame | null>(null);
  const [gameState, setGameState] = useState(gameRef.current?.getGameState());
  const [isPaused, setIsPaused] = useState(false);
  const [showStartMessage, setShowStartMessage] = useState(true);

  const drawPaddle = (ctx: CanvasRenderingContext2D, paddle: Paddle) => {
    ctx.fillStyle = '#3B82F6'; // Blue-500
    ctx.fillRect(paddle.position.x, paddle.position.y, paddle.width, paddle.height);
  };

  const drawBall = (ctx: CanvasRenderingContext2D, ball: Ball) => {
    ctx.beginPath();
    ctx.arc(ball.position.x, ball.position.y, ball.radius, 0, Math.PI * 2);
    ctx.fillStyle = '#EC4899'; // Pink-500
    ctx.fill();
    ctx.closePath();
  };

  const drawBrick = (ctx: CanvasRenderingContext2D, brick: Brick) => {
    if (brick.isAlive) {
      ctx.fillStyle = brick.color;
      ctx.fillRect(brick.position.x, brick.position.y, brick.width, brick.height);
      ctx.strokeStyle = '#1F2937'; // Gray-800 for border
      ctx.lineWidth = 1;
      ctx.strokeRect(brick.position.x, brick.position.y, brick.width, brick.height);
    }
  };

  const drawBricks = (ctx: CanvasRenderingContext2D, bricks: Brick[][]) => {
    bricks.forEach(row => {
      row.forEach(brick => drawBrick(ctx, brick));
    });
  };

  const drawUI = (ctx: CanvasRenderingContext2D) => {
    if (!gameRef.current) return;
    const { score, lives, gameOver, gameWon } = gameRef.current.getGameState();
    ctx.font = '20px "Press Start 2P", cursive';
    ctx.fillStyle = '#E5E7EB'; // Gray-200

    ctx.textAlign = 'left';
    ctx.fillText(`Score: ${score}`, 20, GAME_HEIGHT - 40);
    ctx.textAlign = 'right';
    ctx.fillText(`Lives: ${lives}`, GAME_WIDTH - 20, GAME_HEIGHT - 40);

    if (showStartMessage && !gameOver && !gameWon) {
        ctx.textAlign = 'center';
        ctx.fillStyle = 'rgba(255, 255, 255, 0.8)';
        ctx.font = '24px "Press Start 2P", cursive';
        ctx.fillText('Click to Start', GAME_WIDTH / 2, GAME_HEIGHT / 2 - 30);
        ctx.font = '16px "Press Start 2P", cursive';
        ctx.fillText('Move mouse to control paddle', GAME_WIDTH / 2, GAME_HEIGHT / 2 + 10);
    }

    if (gameOver) {
      ctx.textAlign = 'center';
      ctx.fillStyle = '#EF4444'; // Red-500
      ctx.font = '40px "Press Start 2P", cursive';
      ctx.fillText('GAME OVER', GAME_WIDTH / 2, GAME_HEIGHT / 2 - 20);
      ctx.font = '20px "Press Start 2P", cursive';
      ctx.fillStyle = '#F3F4F6'; // Gray-100
      ctx.fillText('Click to Restart', GAME_WIDTH / 2, GAME_HEIGHT / 2 + 30);
    }

    if (gameWon) {
      ctx.textAlign = 'center';
      ctx.fillStyle = '#10B981'; // Emerald-500
      ctx.font = '40px "Press Start 2P", cursive';
      ctx.fillText('YOU WIN!', GAME_WIDTH / 2, GAME_HEIGHT / 2 - 20);
      ctx.font = '20px "Press Start 2P", cursive';
      ctx.fillStyle = '#F3F4F6'; // Gray-100
      ctx.fillText('Click to Play Again', GAME_WIDTH / 2, GAME_HEIGHT / 2 + 30);
    }
  };

  const gameLoop = useCallback(() => {
    if (!gameRef.current || isPaused || showStartMessage) {
      if (gameRef.current && (gameRef.current.getGameState().gameOver || gameRef.current.getGameState().gameWon)) {
        // Continue rendering UI for game over/win even if paused
      } else {
        requestAnimationFrame(gameLoop);
        return;
      }
    }

    gameRef.current.update();
    setGameState(gameRef.current.getGameState());

    const canvas = canvasRef.current;
    const ctx = canvas?.getContext('2d');
    if (ctx && gameRef.current) {
      ctx.clearRect(0, 0, GAME_WIDTH, GAME_HEIGHT);
      ctx.fillStyle = '#111827'; // Gray-900 background
      ctx.fillRect(0, 0, GAME_WIDTH, GAME_HEIGHT);

      const { paddle, ball, bricks } = gameRef.current.getGameState();
      drawPaddle(ctx, paddle);
      drawBall(ctx, ball);
      drawBricks(ctx, bricks);
      drawUI(ctx);
    }

    requestAnimationFrame(gameLoop);
  }, [isPaused, showStartMessage]);

  useEffect(() => {
    gameRef.current = new BreakoutGame(GAME_WIDTH, GAME_HEIGHT);
    setGameState(gameRef.current.getGameState());

    const canvas = canvasRef.current;
    if (canvas) {
        canvas.width = GAME_WIDTH;
        canvas.height = GAME_HEIGHT;
    }

    const handleMouseMove = (event: MouseEvent) => {
      if (!gameRef.current || isPaused || showStartMessage) return;
      const rect = canvasRef.current?.getBoundingClientRect();
      if (rect) {
        const scaleX = GAME_WIDTH / rect.width;
        const mouseX = (event.clientX - rect.left) * scaleX;
        gameRef.current.movePaddle(mouseX - gameRef.current.paddle.width / 2);
      }
    };

    const handleClick = () => {
        if (!gameRef.current) return;

        if (showStartMessage) {
            setShowStartMessage(false);
            setIsPaused(false);
            gameRef.current.resetGame(); // Start fresh
            return;
        }

        if (gameRef.current.getGameState().gameOver || gameRef.current.getGameState().gameWon) {
            gameRef.current.resetGame();
            setIsPaused(false);
            setShowStartMessage(false); // Don't show start message on restart
        }
    };

    document.addEventListener('mousemove', handleMouseMove);
    canvas?.addEventListener('click', handleClick);

    gameLoop(); // Start the game loop

    return () => {
      document.removeEventListener('mousemove', handleMouseMove);
      canvas?.removeEventListener('click', handleClick);
      // Consider how to stop the game loop if needed, e.g., by not calling requestAnimationFrame
    };
  }, [gameLoop]); // gameLoop is stable due to useCallback

  // Initial draw for start message
  useEffect(() => {
    const canvas = canvasRef.current;
    const ctx = canvas?.getContext('2d');
    if (ctx && gameRef.current && showStartMessage) {
        ctx.clearRect(0, 0, GAME_WIDTH, GAME_HEIGHT);
        ctx.fillStyle = '#111827'; // Gray-900 background
        ctx.fillRect(0, 0, GAME_WIDTH, GAME_HEIGHT);
        drawUI(ctx);
    }
  }, [showStartMessage]);

  return (
    <div className="flex flex-col items-center justify-center w-full h-full bg-gray-800 p-4 select-none">
      <canvas
        ref={canvasRef}
        className="border-2 border-purple-500 rounded-lg shadow-2xl"
        style={{ cursor: showStartMessage || gameState?.gameOver || gameState?.gameWon ? 'pointer' : 'none' }}
      />
      <div className="mt-4 text-center">
        {/* Restart button can be added here if preferred over canvas click for restart */}
        {/* Example: <button onClick={handleRestart} className="...">Restart Game</button> */}
        <p className="text-sm text-gray-400 mt-2">
          Move your mouse to control the paddle. Click to start or restart.
        </p>
      </div>
    </div>
  );
};

export default BreakoutPage;
